import{_ as r,o,c as t,a2 as c}from"./chunks/framework.DdtnLau3.js";const v=JSON.parse('{"title":"Service 规范","description":"","frontmatter":{},"headers":[],"relativePath":"zh/spec/service.md","filePath":"zh/spec/service.md"}'),a={name:"zh/spec/service.md"};function i(d,e,s,p,h,n){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="service-规范" tabindex="-1">Service 规范 <a class="header-anchor" href="#service-规范" aria-label="Permalink to &quot;Service 规范&quot;">​</a></h1><h2 id="当前行为" tabindex="-1">当前行为 <a class="header-anchor" href="#当前行为" aria-label="Permalink to &quot;当前行为&quot;">​</a></h2><p>Service 是持久保存、归属特定 Work 的应用定义。Core 创建容器、管理启用状态、检查就绪，并在恢复后协调生命周期。</p><p>Harness 通过原生 <code>piwork-service-mcp</code> 进程和经过身份验证的 Work 专属控制通道访问 Core。Core 检查资源归属、运行身份、策略和配额。用户应用在 Work 的私有 Docker 网络中运行。</p><h2 id="当前定义和工具" tabindex="-1">当前定义和工具 <a class="header-anchor" href="#当前定义和工具" aria-label="Permalink to &quot;当前定义和工具&quot;">​</a></h2><p>创建 Service 时声明名称、镜像、命令、可选环境变量、工作目录、工作空间访问、端口、就绪和资源设置。准确的必填字段、默认值和嵌套限制见现有 <a href="https://github.com/pphboy/piwork/blob/main/internal/servicemcp/tools.json" target="_blank" rel="noreferrer">MCP JSON schemas</a>，不要用猜测的 Docker Compose 格式替代。</p><p>当前 MCP 工具包括：</p><table tabindex="0"><thead><tr><th>工具</th><th>用途</th></tr></thead><tbody><tr><td><code>deployment_context</code></td><td>查看可用部署上下文。</td></tr><tr><td><code>service_create</code>、<code>service_update</code></td><td>声明或修改 Service。</td></tr><tr><td><code>service_list</code>、<code>service_get</code>、<code>service_logs</code></td><td>观察 Services。</td></tr><tr><td><code>service_start</code>、<code>service_stop</code>、<code>service_restart</code>、<code>service_retry</code>、<code>service_remove</code></td><td>管理生命周期。</td></tr><tr><td><code>operation_get</code></td><td>检查已接受的操作。</td></tr></tbody></table><p>工具以 <code>work-services__</code> 命名空间提供给模型，并受工具策略约束。修改请求需要 <code>idempotencyKey</code>，操作完成前会先返回持久接受结果。保留原始 Service ID 和 Operation ID，供后续检查。</p><h2 id="内存政策" tabindex="-1">内存政策 <a class="header-anchor" href="#内存政策" aria-label="Permalink to &quot;内存政策&quot;">​</a></h2><p>应用 Service 容器不设置 Piwork 内存上限，也不预留 Service 内存。省略的 <code>memoryBytes</code> 规范化为零，合法历史正数仅保留兼容数据，不恢复限制；负数、非整数和不安全整数仍非法。当前投影返回 <code>memoryLimitMode=unlimited</code>，部署上下文返回 <code>serviceMemoryPolicy=unlimited</code> 和 <code>defaultServiceMemoryBytes=0</code>。</p><p>Work/宿主内存核算排除历史 Service 预留，包括配置与导入路径。Agent/helper 内存政策以及原子的 CPU、服务数和卷数准入继续有效。受管恢复替换旧受限 Service 容器并保留身份与 workspace，实际可用内存由宿主及外层部署决定。</p><p>默认 base、单 HTTP 入口、离线工具、持久化与版本自动采用见 <a href="/piwork/zh/guide/web-development.html">Web 开发指南</a>。</p><h2 id="网络和存储" tabindex="-1">网络和存储 <a class="header-anchor" href="#网络和存储" aria-label="Permalink to &quot;网络和存储&quot;">​</a></h2><p>已声明的 HTTP 端口可以通过 Desktop 的认证应用网关访问。容器不会获得任意公网主机端口暴露。平台凭据与应用 cookies 和应用授权保持独立。</p><p>授权后，Services 可以把共享工作空间挂载到 <code>/var/data/workspace</code>。希望携带的应用数据存放在托管存储中。删除 Service 会保留共享工作空间文件；这些文件不是可丢弃的容器数据。</p><p>停止 Work 会保留 Service 定义和启用意图。启动 Work 会恢复已启用的 Services。单独停止 Service，会关闭该意图，直到显式再次启动。</p><h2 id="实验性和未来方向" tabindex="-1">实验性和未来方向 <a class="header-anchor" href="#实验性和未来方向" aria-label="Permalink to &quot;实验性和未来方向&quot;">​</a></h2><p>实验性 brain 的 Service 能力契约增加结构化观察、状态版本、操作身份和验证。应用必须实现契约才能参与；普通网页应用不会自动成为可验证操作端点。</p><p>未来可能有更多能力类型适合 Service 概念。当前运行契约是受管理的应用容器。</p><p>权威来源：<a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/work-services/spec.md" target="_blank" rel="noreferrer">work-services 规范</a>、<a href="https://github.com/pphboy/piwork/blob/main/docs/service-mcp.md" target="_blank" rel="noreferrer">Service MCP 指南</a>和<a href="https://github.com/pphboy/piwork/blob/main/docs/service-access.md" target="_blank" rel="noreferrer">应用访问指南</a>。</p>',21)])])}const m=r(a,[["render",i]]);export{v as __pageData,m as default};
